func (l *LAudit) SearchAudit(
	ctx context.Context,
	cluster string,
	req *v1.GetAuditReqInfo,
) (res *Dao.ElasticsearchDocEntity, err error) {
	if req == nil {
		return nil, errors.New("request is nil")
	}

	conn, ok := elasticsearch.EsConns[cluster]
	if !ok {
		return nil, errors.New("该集群未接入日志中心,请联系运维人员接入")
	}

	var (
		filter  = make([]map[string]interface{}, 0)
		must    = make([]map[string]interface{}, 0)
		mustNot = make([]map[string]interface{}, 0)
	)

	addTermFilter := func(field string, value string) {
		if value == "" {
			return
		}

		filter = append(filter, map[string]interface{}{
			"term": map[string]interface{}{
				field: value,
			},
		})
	}

	addTermsMustNot := func(field string, values []string) {
		if len(values) == 0 {
			return
		}

		mustNot = append(mustNot, map[string]interface{}{
			"terms": map[string]interface{}{
				field: values,
			},
		})
	}

	addExistsMust := func(field string) {
		if field == "" {
			return
		}

		must = append(must, map[string]interface{}{
			"exists": map[string]interface{}{
				"field": field,
			},
		})
	}

	addRegexpMust := func(field string, value string) {
		if value == "" {
			return
		}

		must = append(must, map[string]interface{}{
			"regexp": map[string]interface{}{
				field: map[string]interface{}{
					"value": fmt.Sprintf(".*%s.*", value),
				},
			},
		})
	}

	addTimeRangeFilter := func() {
		if req.StartTime == 0 && req.EndTime == 0 {
			return
		}

		rangeBody := map[string]interface{}{}

		if req.StartTime != 0 {
			rangeBody["from"] = time.Unix(int64(req.StartTime), 0).UTC().Format(time.RFC3339)
			rangeBody["include_lower"] = false
		}

		if req.EndTime != 0 {
			rangeBody["to"] = time.Unix(int64(req.EndTime), 0).UTC().Format(time.RFC3339)
			rangeBody["include_upper"] = false
		}

		filter = append(filter, map[string]interface{}{
			"range": map[string]interface{}{
				"StageTimestamp": rangeBody,
			},
		})
	}

	addUserFilter := func(username string) {
		if username == "" {
			return
		}

		must = append(must, map[string]interface{}{
			"bool": map[string]interface{}{
				"minimum_should_match": 1,
				"should": []map[string]interface{}{
					{
						"term": map[string]interface{}{
							"ImpersonatedUser.Username": username,
						},
					},
					{
						"term": map[string]interface{}{
							"User.Username": username,
						},
					},
				},
			},
		})
	}

	addResultFilter := func(result string) {
		if result == "" {
			return
		}

		switch result {
		case "success", "Success", "SUCCESS":
			filter = append(filter, map[string]interface{}{
				"range": map[string]interface{}{
					"ResponseStatus.Code": map[string]interface{}{
						"gte": 200,
						"lt":  300,
					},
				},
			})
		case "failed", "fail", "failure", "Failed", "FAIL", "FAILED":
			filter = append(filter, map[string]interface{}{
				"range": map[string]interface{}{
					"ResponseStatus.Code": map[string]interface{}{
						"gte": 300,
					},
				},
			})
		default:
			addTermFilter("Result", result)
		}
	}

	buildSystemUserCondition := func() map[string]interface{} {
		return map[string]interface{}{
			"bool": map[string]interface{}{
				"minimum_should_match": 1,
				"should": []map[string]interface{}{
					{
						"regexp": map[string]interface{}{
							"ImpersonatedUser.Username": map[string]interface{}{
								"value": "system:.*",
							},
						},
					},
					{
						"regexp": map[string]interface{}{
							"User.Username": map[string]interface{}{
								"value": "system:.*",
							},
						},
					},
				},
			},
		}
	}

	buildNonSystemUserCondition := func() map[string]interface{} {
		return map[string]interface{}{
			"bool": map[string]interface{}{
				"must_not": []map[string]interface{}{
					buildSystemUserCondition(),
				},
			},
		}
	}

	addScopeFilter := func(scope string) {
		switch scope {
		case "system":
			must = append(must, buildSystemUserCondition())
		case "user":
			must = append(must, buildNonSystemUserCondition())
		default:
			mustNot = append(mustNot, buildSystemUserCondition())
		}
	}

	addDefaultIgnoreResourceFilter := func() {
		if req.IsAll {
			return
		}

		addTermsMustNot("ObjectRef.Resource", []string{
			"selfsubjectaccessreviews",
			"clusterroles",
			"sessions",
			"clusterrolebindings",
			"leases",
			"tokenReview",
		})

		addExistsMust("ImpersonatedUser.Username")
	}

	addTimeRangeFilter()

	if cluster != "" {
		addTermFilter("Cluster", cluster)
	}

	addTermFilter("Verb", req.OperationType)
	addTermFilter("ObjectRef.Resource", req.ResourceType)
	addTermFilter("ObjectRef.Namespace", req.Namespace)

	addRegexpMust("ReferObject.keyword", req.ResourceName)

	addUserFilter(req.UserName)
	addResultFilter(req.Result)
	addScopeFilter(req.Scope)
	addDefaultIgnoreResourceFilter()

	boolQuery := map[string]interface{}{}

	if len(must) > 0 {
		boolQuery["must"] = must
	}

	if len(mustNot) > 0 {
		boolQuery["must_not"] = mustNot
	}

	if len(filter) > 0 {
		boolQuery["filter"] = filter
	}

	query := map[string]interface{}{
		"bool": boolQuery,
	}

	from := PageAdapter(req.PageNo, req.Size)

	queries := map[string]interface{}{
		"query": query,
		"size":  req.Size,
		"from":  from,
		"sort": []map[string]interface{}{
			{
				"StageTimestamp": map[string]interface{}{
					"order": "desc",
				},
			},
		},
	}

	glog.Debugf(ctx, "queries %s", func() string {
		s, _ := json.Marshal(queries)
		return string(s)
	})

	value, err := conn.Query(consts.Audit, queries)
	if err != nil {
		glog.Errorf(ctx, "Failed to query %s by %s query %s", "audit", err, func() string {
			s, _ := json.Marshal(queries)
			return string(s)
		})
		return nil, err
	}

	res = repository.ToElasticsearchDocEntity(value)
	return res, nil
}

