)

// QueryNamespaceSnapshotLogic 命名空间子网快照查询逻辑
func QueryNamespaceSnapshotLogic(ctx context.Context, req *v1.QueryNamespaceSnapshotReq, token string, conf *config.Config) ([]*v1.NamespaceSnapshotItem, error) {

	// 1. 构建 rest config
	restConfig, err := client.BuildRestConfig(conf, req.Cluster, token)
	if err != nil {
		return nil, err
	}

	// 2. 构建 kubeClientBuilder
	kc := kube.KubeClientBuilderFor(restConfig, mycache.AppGlobalCache.Cache).
		Token(token).Cluster(req.Cluster)

	// 3. 查询所有 NamespaceSubnetHistory CR
	list, err := ListNamespaceSubnetHistories(ctx, kc)
	if err != nil {
		return nil, fmt.Errorf("查询 NamespaceSubnetHistory 失败: %w", err)
	}

	// 4. 获取当前集群命名空间子网绑定状态（用于 diff）
	currentBindings, err := getCurrentNamespaceSubnetBindings(ctx, token, req.Cluster, conf)
	if err != nil {
		g.Log().Warningf(ctx, "get current namespace subnet bindings failed: %v, skip diff", err)
		currentBindings = make(map[string]map[string]struct{})
	}

	// 5. 解析 CR 列表并转换
	items := make([]*v1.NamespaceSnapshotItem, 0, len(list.Items))
	for i := range list.Items {
		item, parseErr := toNamespaceSnapshotItem(&list.Items[i], req.Cluster, currentBindings)
		if parseErr != nil {
			g.Log().Warningf(ctx, "parse NamespaceSubnetHistory item failed: %v", parseErr)
			continue
		}
		items = append(items, item)
	}

	// 6. 按创建时间降序排序
	sort.Slice(items, func(i, j int) bool {
		return items[i].CreationTimestamp > items[j].CreationTimestamp
	})

	return items, nil
}

// ListNamespaceSubnetHistories 获取命名空间子网快照列表
func ListNamespaceSubnetHistories(ctx context.Context, kc *kube.KubeClientBuilder) (*unstructured.UnstructuredList, error) {
	ri, err := kc.Group(consts.SubnetHistoryGroup).Kind(consts.NamespaceSubnetHistoryKind).Namespace("").Build()
	if err != nil {
		return nil, err
	}

	return ri.List(ctx, metav1.ListOptions{})
}

// getCurrentNamespaceSubnetBindings 获取当前集群命名空间子网绑定状态
// 调用 QueryNSSubnetLogic 的查询结果来获取当前绑定
func getCurrentNamespaceSubnetBindings(ctx context.Context, token, cluster string, conf *config.Config) (map[string]map[string]struct{}, error) {
	// 调用已有的查询函数获取当前所有命名空间子网
	req := &v1.QueryNamespaceSubnetReq{
		Cluster:  cluster,
		Page:     1,
		PageSize: 999999, // 查全量
	}

	items, _, err := QueryNSSubnetLogic(ctx, req, token, conf)
	if err != nil {
		return nil, err
	}

	// 提取当前有效绑定（排除未绑定的）
	result := make(map[string]map[string]struct{})
	for _, item := range items {
		if item.Namespace == "-" || item.StatusCode == VxnetStatusUnbound {
			continue
		}
		if result[item.Namespace] == nil {
			result[item.Namespace] = make(map[string]struct{})
		}
		result[item.Namespace][item.Subnet] = struct{}{}
	}

	return result, nil
}

// toNamespaceSnapshotItem 将 CR 对象转换为 NamespaceSnapshotItem
func toNamespaceSnapshotItem(
	obj *unstructured.Unstructured,
	cluster string,
	currentBindings map[string]map[string]struct{},
) (*v1.NamespaceSnapshotItem, error) {

	spec, found, err := unstructured.NestedMap(obj.Object, "spec")
	if err != nil || !found {
		return nil, fmt.Errorf("spec not found in CR %s", obj.GetName())
	}

	// 解析 spec
	historySpec := parseNamespaceSubnetHistorySpec(spec)

	// 解析 hostnic JSON 字符串
	snapshotMap, err := parseHostnicJSON(historySpec.Hostnic)
	if err != nil {
		return nil, fmt.Errorf("parse hostnic JSON failed for CR %s: %w", obj.GetName(), err)
	}

	// 展开为绑定列表，同时构建 set 用于 diff
	snapshotBindingSet := make(map[string]map[string]struct{})
	var bindings []*v1.NSSubnetBindingItem

	for ns, subnets := range snapshotMap {
		if ns == "" {
			continue
		}
		if snapshotBindingSet[ns] == nil {
			snapshotBindingSet[ns] = make(map[string]struct{})
		}
		for _, subnet := range subnets {
			if subnet == "" {
				continue
			}
			snapshotBindingSet[ns][subnet] = struct{}{}
			bindings = append(bindings, &v1.NSSubnetBindingItem{
				Namespace: ns,
				Subnet:    subnet,
			})
		}
	}

	sortBindingItems(bindings)

	// diff：当前有但快照没有 → sinceAdded（快照之后新增的绑定）
	var sinceAdded []*v1.NSSubnetBindingItem
	for ns, subnetSet := range currentBindings {
		for subnet := range subnetSet {
			if snapshotBindingSet[ns] == nil || !hasKey(snapshotBindingSet[ns], subnet) {
				sinceAdded = append(sinceAdded, &v1.NSSubnetBindingItem{
					Namespace: ns,
					Subnet:    subnet,
				})
			}
		}
	}

	// diff：快照有但当前没有 → sinceRemoved（快照之后移除的绑定）
	var sinceRemoved []*v1.NSSubnetBindingItem
	for ns, subnetSet := range snapshotBindingSet {
		for subnet := range subnetSet {
			if currentBindings[ns] == nil || !hasKey(currentBindings[ns], subnet) {
				sinceRemoved = append(sinceRemoved, &v1.NSSubnetBindingItem{
					Namespace: ns,
					Subnet:    subnet,
				})
			}
		}
	}

	sortBindingItems(sinceAdded)
	sortBindingItems(sinceRemoved)

	return &v1.NamespaceSnapshotItem{
		Cluster:           cluster,
		Name:              obj.GetName(),
		CreationTimestamp: historySpec.CreationTimestamp,
		Bindings:          bindings,
		SinceAdded:        sinceAdded,
		SinceRemoved:      sinceRemoved,
	}, nil
}

// ==================== 辅助结构体和函数 ====================

// NamespaceSubnetHistorySpec CR 的 spec 结构
type NamespaceSubnetHistorySpec struct {
	CreationTimestamp string // spec.creationTimestamp
	Hostnic           string // spec.hostnic (JSON 字符串)
}

// parseNamespaceSubnetHistorySpec 解析 CR 的 spec 字段
// 实际 CR 结构：
// spec:
//   creationTimestamp: "2026-07-13T02:50:01Z"
//   hostnic: |
//     {"cebpaas-system": ["4100-15-61-186-0-27"],"cert-manager": ["4100-15-61-200-224-27"]}
func parseNamespaceSubnetHistorySpec(spec map[string]interface{}) *NamespaceSubnetHistorySpec {
	item := &NamespaceSubnetHistorySpec{}

	if v, ok := spec["creationTimestamp"].(string); ok {
		item.CreationTimestamp = v
	}

	if v, ok := spec["hostnic"].(string); ok {
		item.Hostnic = strings.TrimSpace(v)
	}

	return item
}

// parseHostnicJSON 解析 hostnic JSON 字符串
// 格式: {"namespace": ["subnet1", "subnet2"], ...}
func parseHostnicJSON(jsonStr string) (map[string][]string, error) {
	if jsonStr == "" {
		return make(map[string][]string), nil
	}

	result := make(map[string][]string)
	if err := json.Unmarshal([]byte(jsonStr), &result); err != nil {
		return nil, err
	}
	return result, nil
}

func hasKey(m map[string]struct{}, key string) bool {
	_, exists := m[key]
	return exists
}

func sortBindingItems(items []*v1.NSSubnetBindingItem) {
	sort.Slice(items, func(i, j int) bool {
		if items[i].Namespace != items[j].Namespace {
			return items[i].Namespace < items[j].Namespace
		}
		return items[i].Subnet < items[j].Subnet
	})
}

