package logic

import (
    "context"
    "sort"
    "strings"

    v1 "your/project/api/v1"
    "your/project/config"
    g "your/project/global"
)

func QueryClusterSubnetHistoryLogic(ctx context.Context, req *v1.QueryClusterSubnetHistoryReq, token string, conf *config.Config) (*v1.QueryClusterSubnetHistoryResp, error) {

    // 1. 获取当前集群实际子网状态（复用现有查询逻辑）
    currentSubnets, err := getCurrentSubnetMap(ctx, req.Cluster, token, conf)
    if err != nil {
        g.Log().Errorf(ctx, "get current subnet failed: %v", err)
        return nil, err
    }

    // 2. 查询该集群所有 History CR
    historyList, err := ListClusterSubnetHistoryCR(ctx, req.Cluster, token, conf)
    if err != nil {
        g.Log().Errorf(ctx, "list cluster subnet history CR failed: %v", err)
        return nil, err
    }

    // 3. 按 revision 降序（最新在前）
    sort.Slice(historyList, func(i, j int) bool {
        return historyList[i].Revision > historyList[j].Revision
    })

    // 4. 分页
    total := len(historyList)
    page, size := req.Page, req.Size
    if page <= 0 {
        page = 1
    }
    if size <= 0 {
        size = 10
    }
    start := (page - 1) * size
    end := start + size
    if start > total {
        start = total
    }
    if end > total {
        end = total
    }
    pagedList := historyList[start:end]

    // 5. 每条 CR 与当前实际状态对比
    records := make([]*v1.ClusterSubnetHistoryItem, 0, len(pagedList))
    for _, history := range pagedList {
        snapshotSet := parseHostnic(history.Hostnic)
        subnets := setToSlice(snapshotSet)

        // 现在有，快照没有 → 快照之后新增的
        var sinceAdded []*v1.SubnetDiffItem
        for id, info := range currentSubnets {
            if _, exists := snapshotSet[id]; !exists {
                sinceAdded = append(sinceAdded, &v1.SubnetDiffItem{
                    ID:   id,
                    Name: info.Name,
                    CIDR: info.CIDR,
                })
            }
        }

        // 快照有，现在没有 → 快照之后移除的
        var sinceRemoved []*v1.SubnetDiffItem
        for id := range snapshotSet {
            if _, exists := currentSubnets[id]; !exists {
                sinceRemoved = append(sinceRemoved, &v1.SubnetDiffItem{ID: id})
            }
        }

        records = append(records, &v1.ClusterSubnetHistoryItem{
            Revision:          history.Revision,
            User:              history.User,
            ChangeCause:       history.ChangeCause,
            CreationTimestamp: history.CreationTimestamp,
            Subnets:           subnets,
            SinceAdded:        sinceAdded,
            SinceRemoved:      sinceRemoved,
        })
    }

    return &v1.QueryClusterSubnetHistoryResp{
        Cluster: req.Cluster,
        Total:   total,
        Records: records,
    }, nil
}

// getCurrentSubnetMap 获取当前集群实际绑定的子网（参考 QueryClusterSubnetLogic）
func getCurrentSubnetMap(ctx context.Context, cluster, token string, conf *config.Config) (map[string]*v1.ClusterSubnetItem, error) {
    // 查 K8s IPPool
    ipPools, err := QueryIPPoolFromK8s(ctx, cluster, token, conf)
    if err != nil {
        return nil, err
    }

    result := make(map[string]*v1.ClusterSubnetItem, len(ipPools))
    for _, ipPool := range ipPools {
        result[ipPool.Name] = &v1.ClusterSubnetItem{
            ID:   ipPool.Name,
            Name: ipPool.Name,
            CIDR: ipPool.CIDR,
        }
    }

    // 查 DB 中 binding 状态的（K8s 还没有但正在绑定的）
    bindingMap, err := SelectClusterActionData(ctx, ActionTypeBind,
        utility.TransClusterToDatabaseCluster(cluster), nil)
    if err == nil {
        for _, ac := range bindingMap {
            if _, exists := result[ac.Name]; !exists {
                result[ac.Name] = &v1.ClusterSubnetItem{
                    ID:   ac.Name,
                    Name: ac.Name,
                    CIDR: ac.Address,
                }
            }
        }
    }

    return result, nil
}

// ========== 工具函数 ==========

func parseHostnic(hostnic string) map[string]struct{} {
    result := make(map[string]struct{})
    if hostnic == "" {
        return result
    }
    for _, line := range strings.Split(hostnic, "\n") {
        line = strings.TrimSpace(line)
        if line != "" {
            result[line] = struct{}{}
        }
    }
    return result
}

func setToSlice(set map[string]struct{}) []string {
    result := make([]string, 0, len(set))
    for k := range set {
        result = append(result, k)
    }
    sort.Strings(result)
    return result
}

func ListClusterSubnetHistoryCR(ctx context.Context, cluster, token string, conf *config.Config) ([]*ClusterSubnetHistorySpec, error) {
    // 1. 构建 rest config & kubeClientBuilder
    restConfig, err := client.BuildRestConfig(conf, cluster, token)
    if err != nil {
        return nil, err
    }
    kubeClientBuilder := kube.KubeClientBuilderFor(restConfig, mycache.AppGlobalCache.Cache).
        Token(token).Cluster(cluster)

    // 2. 获取 dynamic client
    dynamicClient, err := kubeClientBuilder.BuildDynamic()
    if err != nil {
        return nil, err
    }

    // 3. List ClusterSubnetHistory CR（cluster-scoped）
    gvr := schema.GroupVersionResource{
        Group:    "app.cebpaas.io",
        Version:  "v1beta1",
        Resource: "clustersubnethistories",
    }

    list, err := dynamicClient.Resource(gvr).List(ctx, metav1.ListOptions{})
    if err != nil {
        return nil, err
    }

    // 4. 解析
    result := make([]*ClusterSubnetHistorySpec, 0, len(list.Items))
    for _, obj := range list.Items {
        item := parseClusterSubnetHistory(obj)
        if item != nil {
            result = append(result, item)
        }
    }
    return result, nil
}

func parseClusterSubnetHistory(obj unstructured.Unstructured) *ClusterSubnetHistorySpec {
    spec, found, err := unstructured.NestedMap(obj.Object, "spec")
    if err != nil || !found {
        return nil
    }

    item := &ClusterSubnetHistorySpec{}

    if v, ok := spec["revision"].(float64); ok {
        item.Revision = int(v)
    } else if v, ok := spec["revision"].(int64); ok {
        item.Revision = int(v)
    }

    if v, ok := spec["user"].(string); ok {
        item.User = v
    }

    if v, ok := spec["changeCause"].(string); ok {
        item.ChangeCause = v
    }

    if v, ok := spec["creationTimestamp"].(string); ok {
        item.CreationTimestamp = v
    }

    if v, ok := spec["hostnic"].(string); ok {
        item.Hostnic = v
    }

    return item
}

func QueryClusterSubnetLogic(ctx context.Context, req *v1.QueryClusterSubnetReq, token string, conf *config.Config) ([]*v1.ClusterSubnetItem, bool, int, error) {
    var (
        result        = make([]*v1.ClusterSubnetItem, 0)
        isBinding     bool
        IPpoolINk8s   = make(map[string]*v1.ClusterSubnetItem)
        cacheKey      = ""
        bindingSubnet = make([]string, 0)
    )

    ipPools, err := QueryIPPoolFromK8s(ctx, req.Cluster, token, conf)
    if err != nil {
        g.Log().Errorf(ctx, "query ippool from k8s failed: %v", err)
        return nil, false, 0, err
    }

    clusterInfo, err := utility.GetClusterStrucsture(ctx, req.Cluster, conf)
    if err != nil {
        g.Log().Warningf(ctx, "query cluster stack err: %v", err)
    }

    isBinding = utility.CheckClusterType(ctx, clusterInfo, consts.AnnoClusterStackValueA, consts.AnnoClusterProductVIRTUL)

    for _, ipPool := range ipPools {
        item := &v1.ClusterSubnetItem{
            ID:          ipPool.Name,
            Name:        ipPool.Name,
            CIDR:        ipPool.CIDR,
            Allocations: ipPool.Allocations,
            Capacity:    ipPool.Capacity,
            Status:      VxnetBindText(VxnetStatusBinded),
            StatusCode:  VxnetStatusBinded,
            Cluster:     req.Cluster,
        }
        IPpoolINk8s[item.Name] = item
        result = append(result, item)
    }

    bindingMap, err := SelectClusterActionData(ctx, ActionTypeBind, utility.TransClusterToDatabaseCluster(req.Cluster), nil)
    if err != nil {
        g.Log().Warningf(ctx, "query bind info from db failed: %v", err)
    }

    for _, ac := range bindingMap {
        if _, existsInK8s := IPpoolINk8s[ac.Name]; !existsInK8s {
            item := &v1.ClusterSubnetItem{
                ID:         ac.Name,
                Name:       ac.Name,
                CIDR:       ac.Address,
                StatusCode: VxnetStatusBinding,
                Status:     VxnetBindText(VxnetStatusBinding),
                Cluster:    req.Cluster,
            }
            result = append(result, item)
            bindingSubnet = append(bindingSubnet, ac.Name)
        }
    }

    unbindingMap, err := SelectClusterActionData(ctx, ActionTypeUnbind, utility.TransClusterToDatabaseCluster(req.Cluster), nil)
    if err != nil {
        g.Log().Warningf(ctx, "query unbind info from db failed: %v", err)
    }

    for _, ac := range unbindingMap {
        if poolItem, existsInK8s := IPpoolINk8s[ac.Name]; existsInK8s {
            poolItem.Status = VxnetBindText(VxnetStatusUnBinding)
            poolItem.StatusCode = VxnetStatusUnBinding
        } else {
            item := &v1.ClusterSubnetItem{
                ID:         ac.Name,
                Name:       ac.Name,
                CIDR:       ac.Address,
                StatusCode: VxnetStatusUnBinded,
                Status:     VxnetBindText(VxnetStatusUnBinded),
                Cluster:    req.Cluster,
            }
            result = append(result, item)
        }
    }

    var needQueryBindTime []string
    for name, item := range IPpoolINk8s {
        if item.StatusCode == VxnetStatusUnBinding {
            needQueryBindTime = append(needQueryBindTime, name)
        }
        if item.StatusCode == VxnetStatusBinded {
            if !InString(bindingSubnet, item.Name) {
                needQueryBindTime = append(needQueryBindTime, name)
            }
        }
    }

    if len(needQueryBindTime) > 0 {
        bindTimeMap, err := BatchQueryClusterActionLastTime(ctx,
            utility.TransClusterToDatabaseCluster(req.Cluster),
            needQueryBindTime,
            ActionTypeBind,
            []int{ActionStatusSuccess},
            cacheKey)
        if err != nil {
            g.Log().Warningf(ctx, "batch query bind time failed: %v", err)
        }
        for name, times := range bindTimeMap {
            if item, ok := IPpoolINk8s[name]; ok && len(times) > 0 {
                item.BindTime = times[0].FinishTime.Layout(layout)
            }
        }
    }

    var response []*v1.ClusterSubnetItem
    for _, v := range result {
        if req.CIDR != "" {
            if !strings.Contains(v.CIDR, req.CIDR) {
                continue
            }
        }
        if req.Name != "" {
            if v.Name != req.Name {
                continue
            }
        }
        if req.Status != "" {
            if v.Status != req.Status {
                continue
            }
        }
        response = append(response, v)
    }

    sort.SliceStable(response, func(i, j int) bool {
        ni := strings.ToLower(response[i].Name)
        nj := strings.ToLower(response[j].Name)
        if ni != nj {
            return ni < nj
        }
        return response[i].CIDR < response[j].CIDR
    })

    return response, isBinding, len(response), nil
}

