func ListClusterSubnetHistoryCR(ctx context.Context, cluster, token string, conf *config.Config) ([]*ClusterSubnetHistorySpec, error) {
    // 1. 构建 rest config & kubeClientBuilder
    restConfig, err := client.BuildRestConfig(conf, cluster, token)
    if err != nil {
        return nil, err
    }
    kubeClientBuilder := kube.KubeClientBuilderFor(restConfig, mycache.AppGlobalCache.Cache).
        Token(token).Cluster(cluster)

    // 2. 获取 dynamic client
    dynamicClient, err := kubeClientBuilder.BuildDynamic()
    if err != nil {
        return nil, err
    }

    // 3. List ClusterSubnetHistory CR（cluster-scoped）
    gvr := schema.GroupVersionResource{
        Group:    "app.cebpaas.io",
        Version:  "v1beta1",
        Resource: "clustersubnethistories",
    }

    list, err := dynamicClient.Resource(gvr).List(ctx, metav1.ListOptions{})
    if err != nil {
        return nil, err
    }

    // 4. 解析
    result := make([]*ClusterSubnetHistorySpec, 0, len(list.Items))
    for _, obj := range list.Items {
        item := parseClusterSubnetHistory(obj)
        if item != nil {
            result = append(result, item)
        }
    }
    return result, nil
}

func parseClusterSubnetHistory(obj unstructured.Unstructured) *ClusterSubnetHistorySpec {
    spec, found, err := unstructured.NestedMap(obj.Object, "spec")
    if err != nil || !found {
        return nil
    }

    item := &ClusterSubnetHistorySpec{}

    if v, ok := spec["revision"].(float64); ok {
        item.Revision = int(v)
    } else if v, ok := spec["revision"].(int64); ok {
        item.Revision = int(v)
    }

    if v, ok := spec["user"].(string); ok {
        item.User = v
    }

    if v, ok := spec["changeCause"].(string); ok {
        item.ChangeCause = v
    }

    if v, ok := spec["creationTimestamp"].(string); ok {
        item.CreationTimestamp = v
    }

    if v, ok := spec["hostnic"].(string); ok {
        item.Hostnic = v
    }

    return item
}

func SelectAllSubnets(ctx context.Context, cluster []string, name string, searchCIDR string, page, pageSize int) ([]*entity.SubnetClusterInfo, int, error) {
	var (
		dao                = dao.SubnetClusterInfo
		subnetClusterInfos = []*entity.SubnetClusterInfo{}
		err                error
		cacheKey           = "SelectAllSubnets" + strings.Join(cluster, ",") + name + searchCIDR + fmt.Sprintf("%d%d", page, pageSize)
	)

	if data, err := gcache.Get(ctx, cacheKey); err == nil && data != nil {
		if result, ok := data.Val().(*CacheSelectFreeSubnets); ok {
			return result.Item, result.Total, nil
		}
	}

	if page <= 0 {
		page = 1
	}
	if pageSize <= 0 {
		pageSize = 10
	}

	model := dao.Ctx(ctx).Where(do.SubnetClusterInfo{})

	if name != "" {
		model = model.WhereLike("name", "%"+name+"%")
	}
	if searchCIDR != "" {
		model = model.WhereLike(dao.Columns().Cidr, "%"+searchCIDR+"%")
	}
	if len(cluster) > 0 {
		var validClusters []string
		for _, c := range cluster {
			if c != "" {
				validClusters = append(validClusters, c)
			}
		}
		if len(validClusters) > 0 {
			model = model.WhereIn(dao.Columns().Cluster, validClusters)
		}
	}

	model = model.Page(page, pageSize)

	if err := model.Scan(&subnetClusterInfos); err != nil {
		return nil, 0, err
	}

	total, err := model.Count()
	if err != nil {
		return nil, 0, err
	}

	// ===== 新增：查出重复绑定的 name，内存中标记 status=5 =====
	type NameItem struct {
		Name string `json:"name"`
	}
	var duplicateNames []*NameItem
	if err := dao.Ctx(ctx).
		Fields(dao.Columns().Name).
		Group(dao.Columns().Name).
		Having("COUNT(DISTINCT cluster) > 1").
		Scan(&duplicateNames); err == nil {

		duplicateMap := make(map[string]bool, len(duplicateNames))
		for _, item := range duplicateNames {
			duplicateMap[item.Name] = true
		}
		for _, info := range subnetClusterInfos {
			if duplicateMap[info.Name] {
				info.Status = 5
			}
		}
	}
	// ===== 新增结束 =====

	gcache.Set(ctx, cacheKey, &CacheSelectFreeSubnets{
		Item:  subnetClusterInfos,
		Total: total,
	}, time.Duration(consts.DefaultCacheDuration))

	return subnetClusterInfos, total, nil
}

func QueryNSSubnetLogic(ctx context.Context, req *v1.QueryNamespaceSubnetReq, token string, conf *config.Config) ([]*v1.NamespaceSubnetItem, int, error) {
	if req.Page <= 0 {
		req.Page = 1
	}
	if req.PageSize <= 0 {
		req.PageSize = 10
	}

	// 1. 从 K8s 查询命名空间子网
	k8sSubnets, err := QueryNamespaceSubnetsFromK8s(ctx, token, req.Cluster, req, conf)
	if err != nil {
		g.Log().Errorf(ctx, "query namespace subnets from k8s failed: %v", err)
		return nil, 0, err
	}

	// 2. 获取已存在的命名空间
	existingNS, err := getExistingNamespaces(ctx, token, req.Cluster, req, conf)
	if err != nil {
		g.Log().Errorf(ctx, "query namespace subnets from k8s failed: %v", err)
		return nil, 0, err
	}

	// 3. 按名称过滤
	if req.Name != "" {
		var filtered []*entity.NamespaceSubnetEntity
		for _, item := range k8sSubnets {
			if item.Name == req.Name {
				filtered = append(filtered, item)
			}
		}
		k8sSubnets = filtered
	}

	// 4. 构建 configMap 绑定关系和子网名称集合
	configMapBindings := make(map[string]bool)
	subnetNameSet := make(map[string]bool)
	subnetNames := make([]string, 0)
	for _, subnet := range k8sSubnets {
		if subnet.Namespace != "" {
			key := fmt.Sprintf("%s:%s", subnet.Namespace, subnet.Name)
			configMapBindings[key] = true
		}
		if !subnetNameSet[subnet.Name] {
			subnetNames = append(subnetNames, subnet.Name)
			subnetNameSet[subnet.Name] = true
		}
	}

	// 4.5 统计 ConfigMap 中每个子网绑定的不同命名空间数量，判断重复绑定
	configMapNSCount := make(map[string]map[string]bool)
	for _, subnet := range k8sSubnets {
		if subnet.Namespace != "" {
			if configMapNSCount[subnet.Name] == nil {
				configMapNSCount[subnet.Name] = make(map[string]bool)
			}
			configMapNSCount[subnet.Name][subnet.Namespace] = true
		}
	}
	multipleBoundSubnets := make(map[string]bool)
	for name, nsMap := range configMapNSCount {
		if len(nsMap) > 1 {
			multipleBoundSubnets[name] = true
		}
	}

	// 5. 查询数据库中的绑定/解绑操作记录
	dbCluster := utility.TransClusterToDatabaseCluster(req.Cluster)

	nsBindingSubnetAc, err := SelectNsBindingData(ctx, dbCluster, "", subnetNames, "")
	if err != nil {
		g.Log().Warningf(ctx, "query ns binding action from db failed: %v", err)
	}

	nsUnbindingSubnetAc, err := SelectNsUnbondData(ctx, dbCluster, "", subnetNames, "")
	if err != nil {
		g.Log().Warningf(ctx, "query ns unbinding action from db failed: %v", err)
	}

	// 6. 根据 configMap 和数据库记录设置状态
	needQueryBindTime := make([]NSSubnetKey, 0)
	for _, block := range k8sSubnets {
		key := fmt.Sprintf("%s:%s", block.Namespace, block.Name)
		if configMapBindings[key] {
			block.StatusCode = VxnetStatusBinded
			block.Status = VxnetBindText(VxnetStatusBinded)
			if unbindAction, has := nsUnbindingSubnetAc[key]; has {
				block.StatusCode = VxnetStatusUnBinding
				block.Status = VxnetBindText(VxnetStatusUnBinding)
				block.Operator = unbindAction.Operator
				block.OperateTime = unbindAction.OperateTime
			}
			needQueryBindTime = append(needQueryBindTime, NSSubnetKey{
				Name:      block.Name,
				Namespace: block.Namespace,
			})
		} else {
			block.StatusCode = VxnetStatusUnbound
			block.Status = VxnetBindText(VxnetStatusUnbound)
		}
	}

	// 7. 构建子网信息映射
	subnetInfoMap := make(map[string]*entity.NamespaceSubnetEntity)
	for _, block := range k8sSubnets {
		if _, exists := subnetInfoMap[block.Name]; !exists {
			subnetInfoMap[block.Name] = block
		}
	}

	// 8. 处理正在绑定中的记录（数据库有但 configMap 中尚无）
	bindingExpanded := make(map[string]bool)
	var additionalEntries []*entity.NamespaceSubnetEntity
	for key, bindAction := range nsBindingSubnetAc {
		if configMapBindings[key] {
			continue
		}
		if baseBlock, ok := subnetInfoMap[bindAction.Name]; ok {
			newBlock := &entity.NamespaceSubnetEntity{
				Name:        baseBlock.Name,
				CIDR:        baseBlock.CIDR,
				Vxnet:       baseBlock.Vxnet,
				Capacity:    baseBlock.Capacity,
				Allocations: baseBlock.Allocations,
				StatusCode:  VxnetStatusBinding,
				Status:      VxnetBindText(VxnetStatusBinding),
				Namespace:   bindAction.Namespace,
				Operator:    bindAction.Operator,
				OperateTime: bindAction.OperateTime,
			}
			additionalEntries = append(additionalEntries, newBlock)
			bindingExpanded[baseBlock.Name] = true
		}
	}

	// 9. 合并列表：去掉已被 binding 扩展的未绑定条目
	var mergedList []*entity.NamespaceSubnetEntity
	for _, block := range k8sSubnets {
		if block.Namespace == "" && block.StatusCode == VxnetStatusUnbound && bindingExpanded[block.Name] {
			continue
		}
		mergedList = append(mergedList, block)
	}
	mergedList = append(mergedList, additionalEntries...)
	k8sSubnets = mergedList

	// 10. 批量查询绑定完成时间
	bindTimeMap := make(map[string]*gtime.Time)
	if len(needQueryBindTime) > 0 {
		bindTimeMap, err = BatchQueryLastSuccessBindTime(ctx, dbCluster, needQueryBindTime)
		if err != nil {
			g.Log().Warningf(ctx, "query bind time failed: %v", err)
		}
	}

	for _, block := range k8sSubnets {
		if block.StatusCode == VxnetStatusBinded || block.StatusCode == VxnetStatusUnBinding {
			key := fmt.Sprintf("%s:%s", block.Namespace, block.Name)
			if block.StatusCode == VxnetStatusBinded {
				if _, hasBinding := nsBindingSubnetAc[key]; hasBinding {
					block.FinishTime = nil
					continue
				}
			}
			if ft, ok := bindTimeMap[key]; ok {
				block.FinishTime = ft
			}
		}
	}

	// 11. 构建扁平列表，每个子网+命名空间为一行
	subnetItems := make([]*v1.NamespaceSubnetItem, 0, len(k8sSubnets))
	for _, block := range k8sSubnets {
		item := &v1.NamespaceSubnetItem{
			Cluster:         req.Cluster,
			Subnet:          block.Name,
			Vxnet:           block.Vxnet,
			CIDR:            block.CIDR,
			Capacity:        fmt.Sprint(block.Capacity),
			Allocations:     fmt.Sprint(block.Allocations),
			IsMultipleBound: multipleBoundSubnets[block.Name],
		}

		if block.Namespace == "" {
			item.Namespace = "-"
			item.Status = VxnetBindText(VxnetStatusUnbound)
			item.StatusCode = VxnetStatusUnbound
			item.FinishTime = "-"
			item.Operator = "-"
			item.OperateTime = "-"
			item.IsNsDeleted = false
		} else {
			finishTimeStr := "-"
			if block.FinishTime != nil {
				finishTimeStr = block.FinishTime.Layout("2006-01-02 15:04:05")
			}
			_, nsExists := existingNS[block.Namespace]
			item.Namespace = block.Namespace
			item.Status = block.Status
			item.StatusCode = block.StatusCode
			item.FinishTime = finishTimeStr
			item.Operator = defaultIfEmpty(block.Operator, "-")
			item.OperateTime = defaultIfEmpty(block.OperateTime, "-")
			item.IsNsDeleted = !nsExists
		}

		subnetItems = append(subnetItems, item)
	}

	// 12. 分配网络域
	if err := AssignNetworkDomain(ctx, subnetItems); err != nil {
		g.Log().Warningf(ctx, "assign network domain failed: %v", err)
	}

	// 13. 按请求参数过滤
	filteredResult := make([]*v1.NamespaceSubnetItem, 0)
	for _, item := range subnetItems {
		if req.Attribute != "" && item.Attribute != req.Attribute {
			continue
		}
		if req.IP != "" && !strings.Contains(item.CIDR, req.IP) {
			continue
		}
		item.CSegment, err = utils.Parent24CIDR(item.CIDR)
		if err != nil {
			g.Log().Warningf(ctx, "fail to parse address: %v", err)
		}
		if req.Namespace != "" && item.Namespace != req.Namespace {
			continue
		}
		if req.Status != "" && item.Status != req.Status {
			continue
		}
		if req.IsNsDeleted != nil && item.IsNsDeleted != *req.IsNsDeleted {
			continue
		}
		filteredResult = append(filteredResult, item)
	}

	// 14. 排序：先按子网名排序，再按命名空间排序
	totalCount := len(filteredResult)
	sort.SliceStable(filteredResult, func(i, j int) bool {
		si := strings.ToLower(filteredResult[i].Subnet)
		sj := strings.ToLower(filteredResult[j].Subnet)
		if si != sj {
			return si < sj
		}
		return strings.ToLower(filteredResult[i].Namespace) < strings.ToLower(filteredResult[j].Namespace)
	})

	// 15. 分页
	start := (req.Page - 1) * req.PageSize
	end := start + req.PageSize
	if start > totalCount {
		start = totalCount
	}
	if end > totalCount {
		end = totalCount
	}

	return filteredResult[start:end], totalCount, nil
}

func AssignNetworkDomain(ctx context.Context, result []*v1.NamespaceSubnetItem) error {
	var domains []*entity.SubnetAttribute
	model := dao.SubnetAttribute.Ctx(ctx)
	if err := model.Scan(&domains); err != nil {
		return fmt.Errorf("查询网络域失败: %w", err)
	}

	// 记录未匹配到网络域的子网索引
	var unmatchedIndices []int

	for i := range result {
		ip, _, err := net.ParseCIDR(result[i].CIDR)
		if err != nil {
			ip = net.ParseIP(result[i].CIDR)
			if ip == nil {
				continue
			}
		}

		var matchedDomain *entity.SubnetAttribute
		maxMaskSize := -1

		for _, domain := range domains {
			_, domainNet, err := net.ParseCIDR(domain.Ip)
			if err != nil {
				continue
			}
			if domainNet.Contains(ip) {
				maskSize, _ := domainNet.Mask.Size()
				if maskSize > maxMaskSize {
					maxMaskSize = maskSize
					matchedDomain = domain
				}
			}
		}

		if matchedDomain != nil {
			result[i].Attribute = matchedDomain.Attribute
		} else {
			unmatchedIndices = append(unmatchedIndices, i)
		}
	}

	// ===== 新增：对未匹配的子网，通过集群子网的C段进行兜底匹配 =====
	if len(unmatchedIndices) == 0 {
		return nil
	}

	var clusterSubnets []*entity.SubnetClusterInfo
	if err := dao.SubnetClusterInfo.Ctx(ctx).
		WhereNot("attribute", "").
		Scan(&clusterSubnets); err != nil {
		g.Log().Warningf(ctx, "查询集群子网失败，跳过C段匹配: %v", err)
		return nil
	}

	if len(clusterSubnets) == 0 {
		return nil
	}

	// 构建 C段 -> 网络域 的映射
	// key: "192.168.1" value: "金融域"
	cSegmentAttrMap := make(map[string]string)
	for _, cs := range clusterSubnets {
		if cs == nil || cs.Attribute == "" || cs.Cidr == "" {
			continue
		}
		csIP, _, err := net.ParseCIDR(cs.Cidr)
		if err != nil {
			csIP = net.ParseIP(cs.Cidr)
		}
		if csIP == nil {
			continue
		}
		csIPv4 := csIP.To4()
		if csIPv4 == nil || len(csIPv4) < 4 {
			continue
		}
		// 用前3个字节作为C段标识，避免 fmt.Sprintf 拼接 /24 后再解析
		cKey := fmt.Sprintf("%d.%d.%d", csIPv4[0], csIPv4[1], csIPv4[2])
		if _, exists := cSegmentAttrMap[cKey]; !exists {
			cSegmentAttrMap[cKey] = cs.Attribute
		}
	}

	if len(cSegmentAttrMap) == 0 {
		return nil
	}

	// 对未匹配的命名空间子网，尝试用C段匹配
	for _, idx := range unmatchedIndices {
		if idx < 0 || idx >= len(result) || result[idx] == nil {
			continue
		}
		cidr := result[idx].CIDR
		if cidr == "" {
			continue
		}
		ip, _, err := net.ParseCIDR(cidr)
		if err != nil {
			ip = net.ParseIP(cidr)
		}
		if ip == nil {
			continue
		}
		ipv4 := ip.To4()
		if ipv4 == nil || len(ipv4) < 4 {
			continue
		}
		cKey := fmt.Sprintf("%d.%d.%d", ipv4[0], ipv4[1], ipv4[2])
		if attr, ok := cSegmentAttrMap[cKey]; ok {
			result[idx].Attribute = attr
		}
	}

	return nil
}
